<?php

declare(strict_types=1);

namespace jinx\web;

/**
 * Generated Oracle-shaped dispatch table for hot worker-safe PHP builtins.
 *
 * This is the PHP carrier for the same idea as the C Oracle/PASM dispatcher:
 * a validated builtin name enters a compact direct dispatch table instead of
 * the generic worker wrapper metadata path.
 */
final class WebNativeOracleDispatch
{
    /** @var array<string,true>|null */
    private static ?array $names = null;

    public static function has(string $name): bool
    {
        if (self::$names === null) {
            self::$names = array_fill_keys(self::names(), true);
        }

        return isset(self::$names[strtolower($name)]);
    }

    /** @return list<string> */
    public static function names(): array
    {
        return [
            'abs',
            'acos',
            'acosh',
            'addcslashes',
            'addslashes',
            'array_all',
            'array_any',
            'array_change_key_case',
            'array_chunk',
            'array_column',
            'array_combine',
            'array_count_values',
            'array_diff',
            'array_diff_assoc',
            'array_diff_key',
            'array_diff_uassoc',
            'array_diff_ukey',
            'array_fill',
            'array_fill_keys',
            'array_filter',
            'array_find',
