            'array_values',
            'asin',
            'asinh',
            'assert',
            'atan',
            'atan2',
            'atanh',
            'base64_decode',
            'base64_encode',
            'base_convert',
            'basename',
            'bin2hex',
            'bindec',
            'boolval',
            'cal_days_in_month',
            'cal_from_jd',
            'cal_info',
            'cal_to_jd',
            'call_user_func',
            'call_user_func_array',
            'ceil',
            'checkdate',
            'checkdnsrr',
            'chop',
            'chr',
            'chunk_split',
            'class_exists',
            'class_implements',
            'class_parents',
            'class_uses',
            'connection_aborted',
            'connection_status',
            'constant',
            'convert_uudecode',
            'convert_uuencode',
            'cos',
            'cosh',
            'count',
            'count_chars',
            'crc32',
            'crypt',
            'ctype_alnum',
            'ctype_alpha',
            'ctype_cntrl',
            'ctype_digit',
            'ctype_graph',
            'ctype_lower',
            'ctype_print',
        ];
    }

    /**
     * @param list<mixed> $args
     */
    public static function call(string $name, array $args): mixed
    {
        return self::callLowercase(strtolower($name), $args);
    }

    /**
     * @param list<mixed> $args
