        return match ($name) {
            'abs' => abs(...$args),
            'acos' => acos(...$args),
            'acosh' => acosh(...$args),
            'addcslashes' => addcslashes(...$args),
            'addslashes' => addslashes(...$args),
            'array_all' => array_all(...$args),
            'array_any' => array_any(...$args),
            'array_change_key_case' => array_change_key_case(...$args),
            'array_chunk' => array_chunk(...$args),
            'array_column' => array_column(...$args),
            'array_combine' => array_combine(...$args),
            'array_count_values' => array_count_values(...$args),
            'array_diff' => array_diff(...$args),
            'array_diff_assoc' => array_diff_assoc(...$args),
            'array_diff_key' => array_diff_key(...$args),
