            'array_search' => array_search(...$args),
            'array_slice' => array_slice(...$args),
            'array_sum' => array_sum(...$args),
            'array_udiff' => array_udiff(...$args),
            'array_udiff_assoc' => array_udiff_assoc(...$args),
            'array_udiff_uassoc' => array_udiff_uassoc(...$args),
            'array_uintersect' => array_uintersect(...$args),
            'array_uintersect_assoc' => array_uintersect_assoc(...$args),
            'array_uintersect_uassoc' => array_uintersect_uassoc(...$args),
            'array_values' => array_values(...$args),
            'asin' => asin(...$args),
            'asinh' => asinh(...$args),
            'assert' => assert(...$args),
            'atan' => atan(...$args),
            'atan2' => atan2(...$args),
            'atanh' => atanh(...$args),
            'base64_decode' => base64_decode(...$args),
            'base64_encode' => base64_encode(...$args),
            'base_convert' => base_convert(...$args),
            'basename' => basename(...$args),
            'bin2hex' => bin2hex(...$args),
            'bindec' => bindec(...$args),
            'boolval' => boolval(...$args),
            'cal_days_in_month' => cal_days_in_month(...$args),
            'cal_from_jd' => cal_from_jd(...$args),
            'cal_info' => cal_info(...$args),
            'cal_to_jd' => cal_to_jd(...$args),
            'call_user_func' => call_user_func(...$args),
            'call_user_func_array' => call_user_func_array(...$args),
            'ceil' => ceil(...$args),
            'checkdate' => checkdate(...$args),
            'checkdnsrr' => checkdnsrr(...$args),
            'chop' => chop(...$args),
            'chr' => chr(...$args),
            'chunk_split' => chunk_split(...$args),
            'class_exists' => class_exists(...$args),
            'class_implements' => class_implements(...$args),
            'class_parents' => class_parents(...$args),
            'class_uses' => class_uses(...$args),
            'connection_aborted' => connection_aborted(...$args),
            'connection_status' => connection_status(...$args),
            'constant' => constant(...$args),
            'convert_uudecode' => convert_uudecode(...$args),
            'convert_uuencode' => convert_uuencode(...$args),
            'cos' => cos(...$args),
            'cosh' => cosh(...$args),
            'count' => count(...$args),
            'count_chars' => count_chars(...$args),
            'crc32' => crc32(...$args),
            'crypt' => crypt(...$args),
            'ctype_alnum' => ctype_alnum(...$args),
            'ctype_alpha' => ctype_alpha(...$args),
            'ctype_cntrl' => ctype_cntrl(...$args),
            'ctype_digit' => ctype_digit(...$args),
            'ctype_graph' => ctype_graph(...$args),
            'ctype_lower' => ctype_lower(...$args),
            'ctype_print' => ctype_print(...$args),
            default => throw new \RuntimeException("No Oracle dispatch entry for {$name}"),
        };
    }

    /**
     * @param list<mixed> $args
     */
    public static function tryCallLowercase(string $name, array $args, bool &$hit): mixed
    {
        $hit = true;

        return match ($name) {
            'abs' => abs(...$args),
            'acos' => acos(...$args),
            'acosh' => acosh(...$args),
            'addcslashes' => addcslashes(...$args),
