            'array_key_exists' => array_key_exists(...$args),
            'array_key_first' => array_key_first(...$args),
            'array_key_last' => array_key_last(...$args),
            'array_keys' => array_keys(...$args),
            'array_map' => array_map(...$args),
            'array_merge' => array_merge(...$args),
